//! 🚪️ A genuine captured export returns a denied font turn without spinning or losing its original read.
use super::super::*;
use semio_framework_job::{OriginalJobFixtureCaller,OriginalJobDecodeOwner,OriginalTurnFailure,OperationId,Generation,close_original_retained_step};
use semio_framework_value::{RetirementDemand,RetainedCloneGrant,RetainedCloneStep,retirement::controlled::ControlledRetirement};
use semio_framework_trace::observe_heap_allocations_on_this_thread as observe;
use serde_json::Value;
#[global_allocator]
static EXPORT_FONT_HEAP:semio_framework_trace::HeapWitness=semio_framework_trace::HeapWitness;
fn now()->Option<u64>{Some(0)}
fn grant(d:RetirementDemand)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}
fn stock(v:&Value)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:v["items"].as_u64().unwrap()as usize,maximum_copy_bytes:v["copy"].as_u64().unwrap()as usize,maximum_capacity_bytes:v["capacity"].as_u64().unwrap()as usize,maximum_release_bytes:v["release"].as_u64().unwrap()as usize,maximum_depth:v["depth"].as_u64().unwrap()as usize}}
#[semio_framework_async_macros::async_test]
async fn original_export_blocked_font_reservation_returns_to_the_same_caller(){
 let law:Value=serde_json::from_str(include_str!("../../../../../🧬️schema/🎬️scene/🔤️text/🧪️tests/🎟️original/🔣️.json")).unwrap();let rows:Value=serde_json::from_str(include_str!("../../../../../🧪️tests/🧫️fixtures/🎬️scene/📋️prepare/🔣️.json")).unwrap();let source=rows.as_array().unwrap().iter().find(|r|r["name"]==law["source"]).unwrap();let document:DrawingSnapshot=serde_json::from_value(source["document"].clone()).unwrap();
 let mut issuer=store::ArtifactStore::new::<store::os_store::ArtifactSnapshotPublication>(store::os_store::document_materialize::create_document_envelope::<DrawingSnapshot,semio_s_artifact_draw_drawing_mutations::DrawingMutation>("drawing.drawing","original-font-export",document,None,&store::os_vcs::io::binary::genesis::ArtifactPackGenesisProducer),protocol::ActorId(protocol::LOCAL_ACTOR_ID.into())).await.unwrap();issuer.install_document_store_owners_exact(store::os_store::document_store_owners::funded_bounded_artifact_store_owners().unwrap());let generation=issuer.generation().0;let revision=issuer.content_revision_now();let original=issuer.snapshot_read().unwrap();
 let mut producer=ExportProducer::new(original,ExportOptions{format:"svg",width:None,height:None,transparent:true});producer.initialize().unwrap();
 let issued=stock(&law["stock"]);let mut caller=OriginalJobFixtureCaller::admit(OperationId(law["operation"].as_u64().unwrap()),Generation(generation),issued,now,law["deadlineUs"].as_u64().unwrap(),law["fuel"].as_u64().unwrap());let mut decoder=OriginalJobDecodeOwner::empty();let mut reached=false;
 for _ in 0..law["maxObservedTurns"].as_u64().unwrap(){let vector=producer.vector.as_mut().unwrap();let g=grant(vector.next_work_demand());let progress=caller.turn_with_decoder(g,&mut decoder,|cx|Ok::<_,OriginalTurnFailure>(vector.advance_original(cx))).unwrap().unwrap();assert!(!progress.done);if progress.phase=="text"&&vector.next_work_demand().capacity_bytes>0{reached=true;break}}
 assert!(reached);assert!(producer.source_authority_matches(generation,revision));let demand=producer.vector.as_ref().unwrap().next_work_demand();let mut denied=grant(demand);assert!(denied.maximum_capacity_bytes>0);denied.maximum_capacity_bytes-=1;let fuel=caller.fuel_remaining();
 let(result,heap)=observe(||caller.turn_with_decoder(denied,&mut decoder,|cx|Ok::<_,OriginalTurnFailure>(producer.advance(generation,revision,cx))));assert!(!heap.overflowed);assert_eq!(result.unwrap().unwrap(),law["exportBlocked"]["expectedComplete"].as_bool().unwrap());assert_eq!(caller.receipt(),Default::default());assert_eq!(caller.fuel_remaining(),fuel);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(producer.vector.as_ref().unwrap().next_work_demand(),demand);assert_eq!(producer.vector.as_ref().unwrap().last_turn_work(),0);assert!(producer.output().is_none());assert!(producer.source_authority_matches(generation,revision));
 producer.begin_close();for _ in 0..1_000_000{if producer.terminal_is_empty(){break}let d=producer.close_demands(32768).unwrap();caller.turn_with_decoder(grant(d),&mut decoder,|cx|cx.with_original_retirement(|cx|close_original_retained_step(cx,d,|g|producer.close_step(g).map(|step|match step{InteractiveJobCloseStep::Pending{progress}=>RetainedCloneStep::Progress(progress),InteractiveJobCloseStep::Complete{progress}=>RetainedCloneStep::Complete(progress),other=>panic!("funded export close refused: {other:?}")})))).unwrap();}assert!(producer.terminal_is_empty());let((),heap)=observe(||drop(producer));assert!(!heap.overflowed);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));
 let mut returned=None;for _ in 0..1_000_000{if returned.is_none()&&issuer.returned_snapshot_read_count()==0{break}let d=if let Some(owner)=returned.as_ref(){store::os_store::snapshot_read::artifact_retirement_box_demands(owner,32768).unwrap()}else{issuer.returned_snapshot_read_retirement_demand().unwrap()};caller.turn_with_decoder(grant(d),&mut decoder,|cx|cx.with_original_retirement(|cx|close_original_retained_step(cx,d,|g|{if returned.is_some(){store::os_store::snapshot_read::artifact_retirement_box_close_step(&mut returned,g)}else{let(owner,p)=issuer.take_returned_snapshot_read_retirement(g)?;returned=owner;Ok(RetainedCloneStep::Progress(p))}}))).unwrap();}assert!(returned.is_none()&&issuer.returned_snapshot_read_count()==0);
 for _ in 0..1_000_000{if issuer.close_owned_terminal_is_empty(){break}let d=issuer.close_owned_demands(32768).unwrap();caller.turn_with_decoder(grant(d),&mut decoder,|cx|cx.with_original_retirement(|cx|close_original_retained_step(cx,d,|g|issuer.close_owned_step(g)))).unwrap();}assert!(issuer.close_owned_terminal_is_empty());while !decoder.terminal_is_empty(){caller.turn(issued,|cx|cx.with_original_retirement(|cx|{let d=decoder.retirement_demands(32768)?;close_original_retained_step(cx,d,|g|decoder.close_step(g))?;Ok(())})).unwrap();}
 caller.retire(issued);
}
